import type { ChargeReceipt, PaymentGateway } from "./charge.js";

export class StripeGateway implements PaymentGateway {
  constructor(private readonly client: { createIntent(acct: string, amount: number): Promise<{ id: string; amount_received: number }> }) {}
  async charge(accountId: string, cents: number): Promise<ChargeReceipt> {
    const intent = await this.client.createIntent(accountId, cents);
    return { reference: intent.id, settledCents: intent.amount_received };
  }
}

