package com.example.quota;

public final class QuotaGate {
  public enum Decision { ALLOW, QUOTA_EXHAUSTED, SERVICE_UNAVAILABLE }

  private final QuotaClient client;

  public QuotaGate(QuotaClient client) {
    this.client = client;
  }

  public Decision check(String accountId) {
    int left = client.remainingUnits(accountId).orElse(0);
    return left > 0 ? Decision.ALLOW : Decision.QUOTA_EXHAUSTED;
  }
}

