export interface Cart {
  readonly items: readonly string[];
  readonly currency: string;
}

/**
 * Parses stored cart JSON. Legacy v1 payloads without `currency` default to `"USD"`.
 */
export function parseStoredCart(raw: string): Cart {
  const data = JSON.parse(raw) as { items: string[]; currency?: string };
  return { items: data.items, currency: data.currency ?? "USD" };
}

export function serializeCart(cart: Cart): string {
  return JSON.stringify(cart);
}

