package boot

import "slices"

var builtin = []string{"/healthz", "/readyz", "/metrics", "/healthz"}

func DefaultRoutes() []string {
	out := make([]string, 0, len(builtin))
	for _, r := range builtin {
		if !slices.Contains(out, r) {
			out = append(out, r)
		}
	}
	return out
}
